import os
from gen import STEPS,SERV,FAQ,PRICE,NAVL,IDS
CDN='<script src="https://cdn.tailwindcss.com"></script><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script><script src="https://cdn.jsdelivr.net/npm/d3@7/dist/d3.min.js"></script>'
PH=dict(bp="Országház",lanchid="Lánchíd",debrecen="Debrecen",szeged="Szeged",balaton="Balaton",tram="Budapesti villamos",village="Hollókő",market="Pécs, Széchenyi tér",people="Budapest",eger="Eger",esztergom="Esztergom",fisherman="Halászbástya",heroes="Hősök tere",hortobagy="Hortobágy",kecskemet="Kecskemét",nyugati="Nyugati pályaudvar",panelhaz="Lakótelep",pecsdom="Pécsi székesegyház",piac="Nagycsarnok",sopron="Sopron",szentendre="Szentendre",tihany="Tihany",tokaj="Tokaj",visegrad="Dunakanyar")
P=list(PH)
def img(k,cls="w-full h-full object-cover"): return f'<img loading="lazy" src="../img/{k}.jpg" alt="{PH[k]}" class="{cls}">'
def fig(k,cls,cap="text-xs"): return f'<figure class="relative overflow-hidden {cls}">{img(k)}<figcaption class="absolute bottom-0 left-0 right-0 px-2 py-1 bg-black/55 text-white {cap}">{PH[k]}</figcaption></figure>'
def gallery(keys,cls="grid grid-cols-2 md:grid-cols-4 gap-2",h="h-40"): return f'<div class="{cls}">'+"".join(fig(k,h) for k in keys)+'</div>'
MD='<span class="text-[10px] px-1.5 py-0.5 rounded bg-amber-400/25 text-amber-600 font-semibold align-middle">Mintaadat</span>'
def panel(t,ch,card,extra="",h=""):
  return f'<div class="{card}"><div class="flex justify-between items-center mb-3 gap-2"><h3 class="font-semibold text-sm">{t}</h3>{MD}</div><div data-chart="{ch}" class="{h}"></div>{extra}</div>'
CH=[("Megyei hőtérkép — „Támogatod az ötletet?”","map"),("Az avatar-panel korfája (3000 fő)","pyr"),("Régiók megoszlása","region"),("Településtípus","settle"),("Iskolai végzettség (%)","edu"),("Jövedelmi sávok (%)","inc"),("Hírreakció időben","sent"),("Avatar-reakciók szófelhője","words"),("Kampány-előteszt: előtte / utána","ba"),("Árérzékenységi görbe","price"),("Vásárlási tölcsér","funnel"),("Hagyományos kutatás vs. avatar-panel","cmp")]
def charts(card,order=None,grid="grid md:grid-cols-2 lg:grid-cols-3 gap-4",wide=("map","sent","cmp","price")):
  o=""
  for t,c in (order or CH):
    span="md:col-span-2" if c in wide else ""
    o+=f'<div class="{span} reveal">'+panel(t,c,card+" h-full")+'</div>'
  return f'<div class="{grid}">{o}</div>'
def reportpages(card):
  pg=[("1. Vezetői összefoglaló","41% vásárolna, optimális ár 3 990 Ft, legnyitottabb: 18–29 évesek, Közép-Mo.",["w-4/5","w-3/5","w-full","w-2/3"]),("2. Szegmensek","6 szegmens: városi fiatalok, vidéki családosok, nyugdíjasok, …",["w-full","w-1/2","w-3/4"]),("3. Idézetek","„Drágának tartom, de a gyerekeknek megvenném.” — avatar #1842",["w-2/3","w-full","w-1/2"]),("4. Javaslatok","Árazás 3 990 Ft-on, kampányfókusz: Facebook + helyi média vidéken",["w-3/4","w-full","w-2/5"])]
  return '<div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">'+"".join(f'<div class="{card} aspect-[3/4] flex flex-col"><div class="text-[10px] opacity-60 flex justify-between"><span>magorg.hu riport</span><span>Mintaadat</span></div><h4 class="font-bold mt-2">{t}</h4><p class="text-xs mt-2 opacity-80">{d}</p><div class="mt-auto space-y-1.5">'+"".join(f'<div class="h-1.5 rounded bg-current opacity-20 {w}"></div>' for w in ws)+'<div class="flex items-end gap-1 h-14 mt-2">'+"".join(f'<div class="flex-1 bg-current opacity-40 rounded-t" style="height:{h}%"></div>' for h in [40,70,55,90,35,60])+'</div></div></div>' for t,d,ws in pg)+'</div>'
def steps(card,num): return '<div class="grid md:grid-cols-3 gap-4">'+"".join(f'<div class="{card}"><div class="{num}">{i+1:02d}</div><h3 class="text-lg font-bold mt-3">{a}</h3><p class="mt-1 text-sm opacity-80">{b}</p></div>' for i,(a,b) in enumerate(STEPS))+'</div>'
def serv(card): return '<div class="grid md:grid-cols-3 lg:grid-cols-5 gap-4">'+"".join(f'<div class="{card} overflow-hidden !p-0"><div class="h-28">{img(k)}</div><div class="p-4"><h3 class="font-bold">{a}</h3><p class="text-xs mt-1 opacity-80">{b}</p></div></div>' for (a,b),k in zip(SERV,["piac","nyugati","heroes","lanchid","szentendre"]))+'</div>'
def price(card,acc): return '<div class="grid md:grid-cols-3 gap-4">'+"".join(f'<div class="{card}"><span class="text-[10px] px-1.5 py-0.5 rounded bg-amber-400/25 text-amber-600 font-semibold">példa ár</span><h3 class="font-bold mt-2">{a}</h3><div class="text-3xl font-bold {acc} mt-1">{p}</div><p class="text-sm opacity-80 mt-1">{d}</p></div>' for a,p,d in PRICE)+'</div>'
def faq(card): return '<div class="grid md:grid-cols-2 gap-3">'+"".join(f'<details class="{card}"><summary class="cursor-pointer font-semibold">{q}</summary><p class="mt-2 text-sm opacity-80">{a}</p></details>' for q,a in FAQ)+'</div>'
def cta(btn): return f'<form class="mt-6 max-w-xl mx-auto flex flex-col sm:flex-row gap-3" onsubmit="event.preventDefault();this.innerHTML=\'<p class=font-semibold>Köszönjük! (minta űrlap)</p>\'"><input required type="email" placeholder="E-mail címed" class="flex-1 px-4 py-3 rounded-lg text-gray-900 border"><button class="{btn}">Ajánlatot kérek</button></form><p class="text-xs opacity-60 mt-4">Képek: Wikimedia Commons, szabad licencek — <a class="underline" href="../CREDITS.md">forrásmegjelölés</a>. Minden szám, grafikon és hírcím <b>mintaadat</b>, az árak <b>példák</b>. Az avatarok szintetikusak, nem valós személyek.</p>'
def H(t,s,font): return f'<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>magorg.hu — {t}</title>{CDN}<link href="https://fonts.googleapis.com/css2?family={font}&display=swap" rel="stylesheet"><style>{s} canvas{{max-height:300px}} .reveal{{transition:all .8s}}</style></head>'
def nav(cls,brand,btn,lnk=""): return f'<nav class="{cls}"><div class="max-w-7xl mx-auto px-5 h-14 flex items-center justify-between">{brand}<div class="hidden md:flex gap-5 text-sm {lnk}">{"".join(f"<a href=#{i}>{l}</a>" for l,i in zip(NAVL,IDS))}</div><a href="#kapcsolat" class="{btn}">Ajánlatkérés</a></div></nav>'
def S(id,cls,title,inner,h2,sub=""): return f'<section id="{id}" class="{cls}"><div class="max-w-7xl mx-auto px-5"><h2 class="{h2}">{title}</h2>{f"<p class=\"opacity-70 mt-1 mb-6\">{sub}</p>" if sub else "<div class=mb-6></div>"}{inner}</div></section>'
def body_sections(card,num,h2,sa,sb,acc,btn,ctacls,chartgrid=None,order=None):
  o=S("hogyan",sa,"Hogyan működik?",steps(card,num),h2)
  o+=S("panel",sb,"A 3000 fős avatar-panel — Magyarország kicsiben",charts(card,order or CH[:6],chartgrid or "grid md:grid-cols-2 lg:grid-cols-3 gap-4",("map",)),h2,"Életkor, nem, régió, településtípus, végzettség és jövedelem a KSH-arányok szerint. A végleges arányokat KSH-adatokból állítjuk be.")
  o+=S("orszag",sa,"Végig az országon",gallery(P[8:20],"grid grid-cols-2 md:grid-cols-6 gap-2","h-32"),h2,"Budapesttől Tokajig — minden régió és településtípus szerepel a panelben.")
  o+=S("szolg",sb,"Szolgáltatások",serv(card),h2)
  o+=S("elemzes",sa,"Elemzések, amiket kapsz",charts(card,CH[6:],chartgrid or "grid md:grid-cols-2 lg:grid-cols-3 gap-4"),h2,"Hírreakció, szófelhő, kampány-előteszt, árérzékenység, tölcsér — és összevetés a hagyományos kutatással.")
  o+=S("riport",sb,"Mintariport oldalai",reportpages(card),h2)
  o+=S("arak",sa,"Árak",price(card,acc),h2,"Példa árak — a végleges árazás egyeztetés alatt.")
  o+=S("gyik",sb,"Gyakori kérdések",faq(card),h2)
  o+=f'<section id="kapcsolat" class="{ctacls}"><div class="max-w-3xl mx-auto px-5 text-center"><h2 class="{h2}">Mérd meg, mit gondol ma Magyarország.</h2><p class="opacity-80 mt-2">Írd le a kérdésed — 24 órán belül ajánlattal jelentkezünk.</p>{cta(btn)}</div></section>'
  return o
def page(n,html): os.makedirs(f"site/{n}",exist_ok=True);open(f"site/{n}/index.html","w").write(html)
NEWS=[("Emelkedik az üzemanyagár jövő héttől",62,21,17),("Új vasúti menetrend a Balatonnál",28,41,31),("Hosszabb nyitvatartás a kormányablakokban",19,24,57),("Drágul a lakásbérlés a nagyvárosokban",71,18,11)]
def newsw(card,n=4): return "".join(f'<div class="{card}"><p class="text-sm font-semibold">{t}</p><div class="flex h-2 mt-2 rounded overflow-hidden"><div class="bg-rose-500" style="width:{a}%"></div><div class="bg-slate-400" style="width:{b}%"></div><div class="bg-emerald-500" style="width:{c}%"></div></div><div class="flex justify-between text-[11px] mt-1 opacity-70"><span>negatív {a}%</span><span>semleges {b}%</span><span>pozitív {c}%</span></div></div>' for t,a,b,c in NEWS[:n])
KPI=lambda card,c1:"".join(f'<div class="{card}"><div class="text-3xl font-bold tabular-nums {c1}" data-c="{v}">0</div><div class="text-xs opacity-70">{l}</div></div>' for v,l in [(3000,"aktív avatar"),(20,"megye + főváros"),(4,"településtípus"),(48,"demográfiai változó*")])
TH=lambda fg,grid,p,font,**k:"{"+f"fg:'{fg}',grid:'{grid}',p:{p},font:'{font}'"+"".join(f",{a}:'{b}'" for a,b in k.items())+"}"
SC=lambda th,lazy="false":f'<script src="../assets/dash.js"></script><script>MG.render({th},{lazy})</script>'

